import{_ as n,C as r,o as h,c as p,j as d,a as e,E as o,aj as c,w as s}from"./chunks/framework.Cf8CqEYQ.js";const T=JSON.parse('{"title":"dsh-bilibili-hello · 架构 v2","description":"dsh-bilibili-hello 的架构说明：三个会话的分工、关系记忆 v2 的四层与硬预算、事件溯源、协调者模型、安全边界、设置页五页签、HTTP API 与验证手段。已包含提示词瘦身与「宪章归使用者」的改动。","frontmatter":{"title":"dsh-bilibili-hello · 架构 v2","description":"dsh-bilibili-hello 的架构说明：三个会话的分工、关系记忆 v2 的四层与硬预算、事件溯源、协调者模型、安全边界、设置页五页签、HTTP API 与验证手段。已包含提示词瘦身与「宪章归使用者」的改动。","tags":["dsh","bilibili","architecture"],"date":"2026-11-08","layout":"doc","aside":false,"outline":false,"prev":false,"next":false},"headers":[],"relativePath":"artifacts/dsh-bilibili-hello-arch.md","filePath":"artifacts/dsh-bilibili-hello-arch.md"}'),g={name:"artifacts/dsh-bilibili-hello-arch.md"};function m(u,t,b,y,_,f){const i=r("StatGrid"),a=r("MermaidDiagram"),l=r("Callout");return h(),p("div",null,[t[2]||(t[2]=d("h1",{id:"一句话定位",tabindex:"-1"},[e("一句话定位 "),d("a",{class:"header-anchor",href:"#一句话定位","aria-label":'Permalink to "一句话定位"'},"​")],-1)),t[3]||(t[3]=d("p",null,"让一个 Agent 拿你自己的 B站号，在没人管的时候自己刷视频、自己读字幕判断、自己收藏、自己记笔记，到点私信你一句「今天看了这些，我觉得你会喜欢这几个」。",-1)),t[4]||(t[4]=d("p",null,[e("它不是 RPA 脚本，是"),d("strong",null,"一个有自己口味、而且口味会慢慢变的收藏家"),e("：白天的所见写成流水，夜里巩固成一张可查询的图，第二天在干净的上下文里继续逛。")],-1)),o(i,{items:[{label:"三个会话的工具数",value:"27 / 5 / 31"},{label:"关系边上限",value:"600"},{label:"DIGEST 注入上限",value:"4000 字"},{label:"单轮 scratch 上限",value:"4000 字"},{label:"记忆节点类型",value:"6 种 / 9 种关系"},{label:"测试",value:"343 例全绿"}]}),t[5]||(t[5]=c('<hr><h2 id="_1-三个会话-一台机器" tabindex="-1">1. 三个会话，一台机器 <a class="header-anchor" href="#_1-三个会话-一台机器" aria-label="Permalink to &quot;1. 三个会话，一台机器&quot;">​</a></h2><p>同一个插件里有三个<strong>独立进程、独立上下文</strong>的轮次，它们共享同一张口味图、同一份运行状态、同一套章程。</p><table tabindex="0"><thead><tr><th>轮次</th><th>谁来触发</th><th>怎么跑</th><th>工具</th><th>能写什么</th></tr></thead><tbody><tr><td><strong>值班轮</strong> <code>duty</code></td><td>时段窗口（默认 <code>12:00-14:00</code>、<code>18:00-23:30</code>）、设置页「现在跑一轮」、协调者请求</td><td>子进程 <code>dsh --profile bili-hello-duty --print</code>，<code>BILI_HELLO_ROUND_MODE=duty</code></td><td>27</td><td>只能写 L0 流水；收藏 / 关注 / 日报 / 私信</td></tr><tr><td><strong>巩固轮</strong> <code>consolidate</code></td><td>每天 <code>23:50</code>（可关），或设置页「立即整理」</td><td>同 profile，<code>mode=consolidate</code></td><td>5</td><td>任意记忆 op，可压缩图</td></tr><tr><td><strong>回私信轮</strong> <code>reply</code></td><td>私信监听每 3 分钟一跳（只看白名单）</td><td>同 profile，<code>mode=reply</code>，固定续同一条会话</td><td>31</td><td>只读浏览 + <code>curator_*</code> + 回私信；<strong>没有</strong>收藏 / 关注 / 日报</td></tr></tbody></table><ul><li>每一轮都是<strong>新起的子进程</strong>，退出后宿主写 <code>duty.log</code>、<code>metrics/&lt;日期&gt;.jsonl</code>、<code>state/last-round.json</code>，并更新配额。</li><li>宿主会话（你在 Web GUI 里聊天的那个）默认<strong>零注入</strong>：<code>toolsInHost=false</code>，测试断言宿主工具数 = 0。</li><li><code>reply</code> 轮之外，收藏家<strong>没有对话能力</strong> —— 所以「使用者今天突然想换口味」只能由协调者转译成指令（见第 5 节）。</li></ul><hr><h2 id="_2-架构" tabindex="-1">2. 架构 <a class="header-anchor" href="#_2-架构" aria-label="Permalink to &quot;2. 架构&quot;">​</a></h2>',7)),o(a,{"source-b64":""}),t[6]||(t[6]=c('<ul><li><strong>prompt 是 argv 传的</strong>，不走 stdin；提示词由宿主按当前配置和当前图拼出来，同一份配置 ⇒ 同一份 prompt（可预览、可快照）。</li><li>三个轮次共享三样东西：<code>memory/</code>（口味图 + 冷归档 + DIGEST）、<code>state/</code>（跨会话运行态）、<code>prompts/</code>（三份章程）。</li><li>一轮结束后：值班轮写 <code>last-round</code>、清空待看队列；巩固轮滚动情景记忆、把旧版 <code>MEMORY.md</code> 改名留档。</li></ul><hr><h2 id="_3-记忆系统-v2" tabindex="-1">3. 记忆系统 v2 <a class="header-anchor" href="#_3-记忆系统-v2" aria-label="Permalink to &quot;3. 记忆系统 v2&quot;">​</a></h2><h3 id="_3-1-四层" tabindex="-1">3.1 四层 <a class="header-anchor" href="#_3-1-四层" aria-label="Permalink to &quot;3.1 四层&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层</th><th>文件</th><th>谁写</th><th>生命周期</th></tr></thead><tbody><tr><td><strong>L0</strong></td><td><code>memory/scratch/&lt;日期&gt;.md</code></td><td>值班轮 <code>memory_log</code>（唯一写入口）</td><td>单轮流水，整理后丢；硬顶 4000 字</td></tr><tr><td><strong>L1</strong></td><td><code>memory/graph.json</code></td><td>压缩器（投影）</td><td>长期，<strong>有界</strong>，预算由代码强制</td></tr><tr><td><strong>L2</strong></td><td><code>memory/archive/&lt;年-月&gt;.jsonl</code></td><td>驱逐时追加</td><td><strong>无界</strong>，只追加，<code>memory_recall</code> 能搜</td></tr><tr><td><strong>L3</strong></td><td><code>memory/DIGEST-duty.md</code> · <code>DIGEST-reply.md</code></td><td>渲染器（代码生成，绝不手写）</td><td>缓存，可随时重建；硬顶 4000 字</td></tr></tbody></table><h3 id="_3-2-图模型" tabindex="-1">3.2 图模型 <a class="header-anchor" href="#_3-2-图模型" aria-label="Permalink to &quot;3.2 图模型&quot;">​</a></h3><p>节点类型是<strong>封闭集合</strong>，每种有独立上限；关系也是封闭集合。</p><table tabindex="0"><thead><tr><th>节点</th><th>含义</th><th>上限</th></tr></thead><tbody><tr><td><code>up</code></td><td>UP 主</td><td>80</td></tr><tr><td><code>topic</code></td><td>主题 / 分区 / 圈层</td><td>60</td></tr><tr><td><code>video</code></td><td>值得单独记住的视频（<strong>不是播放历史</strong>）</td><td>120</td></tr><tr><td><code>taste</code></td><td>第一人称的口味断言</td><td>24</td></tr><tr><td><code>rule</code></td><td>禁忌 / 规矩（含使用者当下的指令）</td><td>24</td></tr><tr><td><code>open</code></td><td>悬念 / 想追的系列</td><td>16</td></tr></tbody></table><p>九种关系：<code>likes</code> <code>dislikes</code> <code>about</code> <code>authored</code> <code>supports</code> <code>contradicts</code> <code>similar_to</code> <code>superseded_by</code> <code>part_of</code>。</p><p>节点字段：<code>id</code>（<code>&lt;type&gt;:&lt;slug&gt;</code>）、<code>t</code>、<code>w</code>（0..1，代码 clamp）、<code>first</code> / <code>last</code>、<code>until</code>、<code>pin</code>、<code>notes</code>（≤200 字）、<code>ev</code>（≤5 条 × 120 字）。</p><p><strong>双时间（<code>until</code>）</strong>：写上 <code>until</code> 的节点/边退出渲染与检索，但<strong>留在图里</strong>。<code>supersede(old,new)</code> = 给 old 打 <code>until</code> + 加一条 <code>superseded_by</code> 边。所以口味演化不覆盖历史、只失效，<code>/memory/history</code> 直接读它。</p><h3 id="_3-3-硬预算-lib-memory-mjs-的-budget" tabindex="-1">3.3 硬预算（<code>lib/memory.mjs</code> 的 <code>BUDGET</code>） <a class="header-anchor" href="#_3-3-硬预算-lib-memory-mjs-的-budget" aria-label="Permalink to &quot;3.3 硬预算（`lib/memory.mjs` 的 `BUDGET`）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>上限</th><th>超了怎么办</th></tr></thead><tbody><tr><td>每类节点数</td><td>见上表（80 / 60 / 120 / 24 / 24 / 16）</td><td>按驱逐分踢最弱的</td></tr><tr><td>关系边总数</td><td>600</td><td>同上</td></tr><tr><td>单节点证据</td><td>5 条 × 120 字</td><td>只保留最新 5 条</td></tr><tr><td><code>notes</code></td><td>200 字</td><td>硬截断 + 记日志</td></tr><tr><td><code>graph.json</code> 序列化</td><td>256 KB</td><td>触发全图驱逐直到达标</td></tr><tr><td><code>DIGEST-duty.md</code> / <code>DIGEST-reply.md</code></td><td>4000 字（<code>memoryBudget</code> 可配）</td><td>按章节预算整块降级，<strong>绝不截成半句话</strong></td></tr><tr><td>单轮 scratch</td><td>4000 字</td><td>拒绝追加，回一句「该整理了」</td></tr><tr><td><code>pin</code> 的数量</td><td>12</td><td>再 pin 就拒绝（全钉了等于没预算）</td></tr></tbody></table><p>驱逐分：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>score = w × 0.5^(age_days / 45) × (1 + 0.3 × ln(1 + ev.length))</span></span>\n<span class="line"><span>pin ⇒ ∞；until 有值 ⇒ × 0.2</span></span></code></pre></div><p>低者先出局，同分按 id 稳定排序（快照测试才不会飘）。被踢的<strong>全部</strong>写进 <code>archive/&lt;ym&gt;.jsonl</code>，带 <code>why</code>（<code>evicted</code> / <code>evicted:orphan</code> / <code>evicted:oversize</code>），一条都不静默丢。</p>',16)),o(l,{kind:"info",title:"为什么写死在代码里"},{default:s(()=>[...t[0]||(t[0]=[e(" 旧版只在提示词里写一句「约 6000 字符」，没有任何东西强制它，超了就静默截断，使用者从没见过上限。现在预算是一张常量表：构造超限数据 → 驱逐 → 每类节点数、边数、图体积都达标，且被驱逐项全部出现在冷归档里，这条有验收测试盯着。 ",-1)])]),_:1}),t[7]||(t[7]=c(`<h3 id="_3-4-事件溯源-journal-是真相-graph-json-是投影" tabindex="-1">3.4 事件溯源：journal 是真相，graph.json 是投影 <a class="header-anchor" href="#_3-4-事件溯源-journal-是真相-graph-json-是投影" aria-label="Permalink to &quot;3.4 事件溯源：journal 是真相，graph.json 是投影&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>memory/</span></span>
<span class="line"><span>  journal/&lt;ts&gt;-&lt;pid&gt;-&lt;seq&gt;-&lt;writer&gt;.json   ← 每个写者只创建自己那批</span></span>
<span class="line"><span>  graph.json                               ← 压缩后的投影（只有 compactor 写）</span></span>
<span class="line"><span>  DIGEST-&lt;view&gt;.md                         ← 渲染物，可随时重建</span></span>
<span class="line"><span>  archive/&lt;ym&gt;.jsonl                       ← 被驱逐的，只追加</span></span>
<span class="line"><span>  scratch/&lt;day&gt;.md                         ← 值班轮流水</span></span></code></pre></div><ul><li><strong>写</strong>：临时文件 + <code>rename</code> 原子落一个新批次。三个写者各写各的文件，<strong>没有共享可变文件 ⇒ 无锁也安全</strong>。</li><li><strong>读</strong>：<code>graph.json</code> + 按 <code>(at, writer, pid, seq)</code> 叠加还没压缩的批次（正常 0~3 批，开销可忽略）。</li><li><strong>压缩</strong>：<code>mkdir</code> 当互斥锁（原子），锁超过 5s 就放弃、下次再来，<strong>绝不阻塞读</strong>；压缩后删掉已应用的批次。</li><li>好处：天然审计（谁在什么时候因为什么改了记忆）、崩溃安全、可重放，连「使用者让我改口味」本身也是一条可追溯的记录。</li></ul><h3 id="_3-5-写者权限梯度" tabindex="-1">3.5 写者权限梯度 <a class="header-anchor" href="#_3-5-写者权限梯度" aria-label="Permalink to &quot;3.5 写者权限梯度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>写者</th><th>会话</th><th>能写</th></tr></thead><tbody><tr><td><code>duty</code></td><td>值班轮</td><td><strong>只能</strong>写 <code>scratch/&lt;day&gt;.md</code>；改图会被代码直接拒绝</td></tr><tr><td><code>consolidator</code></td><td>巩固轮</td><td>任意 op，含 <code>mk</code> / <code>supersede</code> / <code>forget</code>，可压缩</td></tr><tr><td><code>dm</code></td><td>回私信轮</td><td><code>mk rule[source=user]</code>、<code>mk open</code>、<code>link</code>、<code>obs</code>、<code>pin</code>；不能 <code>forget</code> / <code>weaken</code> / <code>supersede</code>，不能改 <code>taste</code></td></tr></tbody></table><p>理由：白天快速编码、夜间慢速重整。私信轮听到的是<strong>你的原话</strong>，所以它能写「指令」和「想追的东西」，但不能凭一句聊天改写口味画像 —— 那要走巩固。</p><h3 id="_3-6-巩固轮输出的是操作补丁-不是散文" tabindex="-1">3.6 巩固轮输出的是操作补丁，不是散文 <a class="header-anchor" href="#_3-6-巩固轮输出的是操作补丁-不是散文" aria-label="Permalink to &quot;3.6 巩固轮输出的是操作补丁，不是散文&quot;">​</a></h3><p>整份重写散文 = 每次一次有损压缩，演化史全丢。现在只有一个写入口：<code>memory_apply_ops(ops)</code>。</p><table tabindex="0"><thead><tr><th>op</th><th>干什么</th></tr></thead><tbody><tr><td><code>mk</code></td><td>新建节点</td></tr><tr><td><code>obs</code></td><td>观察 / 强化一条关系（高频操作）</td></tr><tr><td><code>link</code> / <code>unlink</code></td><td>连一条边 / 删一条明显错的边</td></tr><tr><td><code>weaken</code></td><td>降权（看腻了、不灵了）</td></tr><tr><td><code>supersede</code></td><td>口味迁移：旧的失效，新的接上</td></tr><tr><td><code>forget</code></td><td>记错了，删掉</td></tr><tr><td><code>pin</code> / <code>unpin</code></td><td>钉住免驱逐 / 解除</td></tr></tbody></table><p>代码侧规则：</p><ul><li>逐条校验、逐条拒绝：未知 op / 未知 id / 非法 weight 进 <code>rejected</code>，其余照常应用 —— <strong>一条坏 op 不许废掉整轮</strong>。</li><li>幂等：同一 <code>(id, rel, toward, ev)</code> 重复提交不重复加权重（读路径每次都会重放 journal，不幂等图就会漂）。</li><li>应用后自动跑一遍预算 + 驱逐，返回 <code>{applied, rejected, evicted, budget}</code>，让它当场看见「我快满了」。</li><li>模型吐出来的原始文本先过 <code>lib/memory-ops.mjs</code>：剥掉 json 代码围栏、切出 JSON 本体、容忍单引号与尾逗号，实在不行退回行式 DSL。解析失败就说「这次没听懂」，不抛异常把整轮搞崩。</li></ul><h3 id="_3-7-两个-digest-视图-同一张图" tabindex="-1">3.7 两个 DIGEST 视图，同一张图 <a class="header-anchor" href="#_3-7-两个-digest-视图-同一张图" aria-label="Permalink to &quot;3.7 两个 DIGEST 视图，同一张图&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th><code>duty</code> 视图</th><th><code>reply</code> 视图</th></tr></thead><tbody><tr><td>当前指令 / 禁忌（<code>rule</code>，置顶）</td><td>300</td><td>300</td></tr><tr><td>我是谁（<code>taste</code> → <code>self</code>）</td><td>900</td><td>500</td></tr><tr><td>口味</td><td>1000</td><td>500</td></tr><tr><td>UP</td><td>800</td><td>600</td></tr><tr><td>主题</td><td>700</td><td>400</td></tr><tr><td>待跟进</td><td>300</td><td>300</td></tr><tr><td>今天的额度 / 最近一轮</td><td>—</td><td>由宿主额外注入（260 + 300）</td></tr></tbody></table><ul><li><code>duty</code> 六章合计正好 4000；<code>reply</code> 让出约 1400 给「今天刷了什么 / 配额」。</li><li><code>video</code> 节点<strong>故意没有章节</strong>：它是「值得单独记住的一条」，不是口味画像，全量注入纯属烧 token，靠 <code>memory_node_get</code> / <code>memory_recall</code> 按需取。</li><li>渲染是纯函数（<code>now</code> 由参数传入，不读 <code>Date.now()</code>）⇒ 同图 + 同 now 逐字节相同，可快照测试。</li></ul><hr><h2 id="_4-协调者模型" tabindex="-1">4. 协调者模型 <a class="header-anchor" href="#_4-协调者模型" aria-label="Permalink to &quot;4. 协调者模型&quot;">​</a></h2><p>你的话：<em>PM Agent 需要有权利知道并且干预刷视频 Agent 的行为，相当于 Coordinator。</em></p>`,17)),o(a,{"source-b64":""}),t[8]||(t[8]=c('<h3 id="_4-1-七个协调者工具-只在-reply-注册" tabindex="-1">4.1 七个协调者工具（只在 <code>reply</code> 注册） <a class="header-anchor" href="#_4-1-七个协调者工具-只在-reply-注册" aria-label="Permalink to &quot;4.1 七个协调者工具（只在 `reply` 注册）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>干预什么</th><th>边界</th></tr></thead><tbody><tr><td><code>curator_status()</code></td><td>今天挑了几条、配额、窗口、是否在跑、最近一轮摘要、待看队列</td><td>只读</td></tr><tr><td><code>curator_directive(text, ttlDays?)</code></td><td>写一条指令（进图，<code>rule</code> + <code>source:&quot;user&quot;</code>）</td><td>≤200 字；最多 12 条有效；ttl 1–365 天，默认 7</td></tr><tr><td><code>curator_queue(bvid | keyword, why)</code></td><td>塞「下一轮请一定看这个」</td><td>队列上限 8 条</td></tr><tr><td><code>curator_set(knob, value)</code></td><td><code>perDay</code>(1–50) / <code>maxFollowPerDay</code>(0–20) / <code>searchSort</code>(4 值) / <code>excludeWords</code></td><td>白名单 + clamp，写不进别的键</td></tr><tr><td><code>curator_pause(minutes)</code></td><td>暂停值班</td><td>5–1440 分钟，传 0 立刻恢复</td></tr><tr><td><code>curator_run(why)</code></td><td>请求现在跑一轮</td><td>30 分钟冷却，返回 <code>queued</code> 或 <code>cooldown</code></td></tr><tr><td><code>curator_remember(text, as)</code></td><td>写一条受限记忆（<code>note</code> / <code>open</code> / <code>rule</code>）</td><td>走 <code>dm</code> 写者权限</td></tr></tbody></table><h3 id="_4-2-明确不给协调者的" tabindex="-1">4.2 明确不给协调者的 <a class="header-anchor" href="#_4-2-明确不给协调者的" aria-label="Permalink to &quot;4.2 明确不给协调者的&quot;">​</a></h3><ul><li>改 provider / 模型路由、改收藏夹、加工具、删历史、<code>forget</code>。</li><li>绕过 <code>perDay</code>（只能调到 clamp 上限）。</li><li>替值班轮刷视频：<code>reply</code> 不注册 <code>hello_favorite</code> / <code>hello_follow</code> / <code>hello_report</code>，也不消耗任何额度。它能<strong>看</strong>（搜索 / 字幕 / 评论 / 取帧）只是为了回答你的问题。</li><li>给任何人发私信：收件人只限白名单（登录账号本人 + <code>dmAllow</code>）。</li></ul><h3 id="_4-3-指令怎么进入下一轮" tabindex="-1">4.3 指令怎么进入下一轮 <a class="header-anchor" href="#_4-3-指令怎么进入下一轮" aria-label="Permalink to &quot;4.3 指令怎么进入下一轮&quot;">​</a></h3><ol><li><code>curator_directive</code> → 写一批 op 进 <code>journal/</code>（writer=<code>dm</code>）→ 成为 <code>rule</code> 节点（<code>source:&quot;user&quot;</code>）。</li><li>下一轮值班的 DIGEST 里，「禁忌与指令」章节<strong>置顶</strong>；章程里写明：<em>指令是他当下说的话，优先级高于你的口味推断</em>。</li><li>指令带 <code>ttlDays</code>，过期自动打 <code>until</code>（双时间），不会永久污染口味图。</li><li>过期 / 被新指令取代的进 <code>/memory/history</code>，在「记忆 → 演化」里能看到。</li><li>队列走另一条路：<code>state/queue.json</code>，值班轮的 prompt 直接读出「使用者刚点名要你看的」，这一轮跑完就清空。</li></ol><hr><h2 id="_5-安全边界" tabindex="-1">5. 安全边界 <a class="header-anchor" href="#_5-安全边界" aria-label="Permalink to &quot;5. 安全边界&quot;">​</a></h2><p>值班轮<strong>无人值守</strong>，而且专门读不可信的第三方内容（标题、简介、字幕、评论、弹幕）。所以它的权限是靠<strong>不给</strong>来保证的，不是靠叮嘱。</p><h3 id="_5-1-值班-profile-关掉的东西-profile-template-bili-hello-duty-cordis-patch-yml" tabindex="-1">5.1 值班 profile 关掉的东西（<code>profile-template/bili-hello-duty/cordis.patch.yml</code>） <a class="header-anchor" href="#_5-1-值班-profile-关掉的东西-profile-template-bili-hello-duty-cordis-patch-yml" aria-label="Permalink to &quot;5.1 值班 profile 关掉的东西（`profile-template/bili-hello-duty/cordis.patch.yml`）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>关掉的条目</th></tr></thead><tbody><tr><td>命令执行</td><td><code>tool-bash</code> <code>tool-pwsh</code> <code>tool-jobs</code> <code>jobs</code></td></tr><tr><td>文件系统 读/写/搜</td><td><code>tool-fs</code> <code>tool-fs-search</code></td></tr><tr><td>联网</td><td><code>tool-web</code> <code>web-fetch-http</code> <code>web-search-deepseek</code></td></tr><tr><td>子代理 / 工作流</td><td><code>tool-subagent*</code> <code>subagent</code> <code>subagent-fork-in-process</code> <code>subagent-spawn-in-process</code> <code>workflow-ptc</code> <code>ptc-runtime</code> <code>tool-workflow</code></td></tr><tr><td>技能（会读文件）</td><td><code>skill</code> <code>skill-filesystem</code> <code>tool-skill</code></td></tr><tr><td>自动读 AGENTS.md</td><td><code>agent-instructions</code></td></tr><tr><td>装插件 / 热重载</td><td><code>tool-plugin-manager</code> <code>plugin-manager</code> <code>hmr</code></td></tr><tr><td>目标 / 计划 / 待办</td><td><code>goal</code> <code>command-goal</code> <code>tool-goal</code> <code>goal-round-driver</code> <code>plan-mode</code> <code>tool-todo</code></td></tr><tr><td>MCP 资源</td><td><code>mcp-resources</code></td></tr></tbody></table><p>同时补开：<code>credentials</code> / <code>authorization</code> / <code>deepseek-account</code>（模型要用账号额度）。</p>',12)),o(l,{kind:"warn",title:"为什么必须整个拿掉文件系统"},{default:s(()=>[...t[1]||(t[1]=[e(" DSH 的沙箱只限制「写」，**读是不受限的**。留一个 `tool-fs` 在值班 profile 里，它就能读 `~/.dsh/sessions/**`（全部会话记录）、凭证、工作区。所以修法不是「叮嘱它别读」，而是不给它文件系统 —— 记录一律走插件自己的窄口工具，路径定死、不接受路径参数。 ",-1)])]),_:1}),t[9]||(t[9]=c(`<ul><li><code>disabled: true</code> 的条目<strong>只许增不许减</strong>：减一条就是把权限还回去。</li><li>铺不上专用 profile 时<strong>明确降级</strong>并在日志里写「这一轮退回了 headless（权限更大）」，不静默。</li></ul><h3 id="_5-2-其余边界" tabindex="-1">5.2 其余边界 <a class="header-anchor" href="#_5-2-其余边界" aria-label="Permalink to &quot;5.2 其余边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th>边界</th><th>实现</th></tr></thead><tbody><tr><td>宿主会话零工具注入</td><td><code>toolsInHost</code> 默认 false；<code>test/apply.test.mjs</code> 断言宿主工具数 = 0</td></tr><tr><td>图床请求不带 Cookie</td><td><code>lib/vision.mjs</code> 的 <code>imageHeaders()</code> 只有 <code>User-Agent</code> + <code>Referer</code>；地址一律强制 https</td></tr><tr><td>头像 / 封面防盗链</td><td>界面统一 <code>referrerPolicy=&quot;no-referrer&quot;</code>（带站外 Referer 会 403）</td></tr><tr><td>私信长度与排版</td><td>一条实测上限约 500 字符，一轮只发一条；回私信 100 字以内。B站私信不解析 Markdown，所以 <code>hello_pm</code> 在发送前用 <code>toPlainChat()</code> 洗掉 <code>**粗体**</code> / <code>\`代码\`</code> / <code>#</code> 标题 / <code>-</code> 列表 / <code>[文字](链接)</code> / <code>&gt;</code> 引用 —— 章程里写的是「请你」，这里是「保证」</td></tr><tr><td>只回白名单</td><td>陌生 UID 只在头一条记一次日志（<code>dm-ignored.json</code> 水位），不回复、不 fetchMessages；<strong>也不标已读</strong>（SDK 没有 ack，标了会把别人的消息从你 App 里藏掉）</td></tr><tr><td>私信先跑成再记账</td><td>顺序反了会丢消息：赶上值班轮 busy 时消息已被标处理 ⇒ 永远不回。有回归测试盯着</td></tr><tr><td>评论裁字段</td><td><code>minComment()</code> 只留 用户名 / uid / 内容（+ rpid / 子楼数），等级、徽章、时间戳、点赞数全裁</td></tr><tr><td>不挂通用 MCP</td><td>那个 server 有 47 个工具，含沙箱里执行任意 JS 和动态调 469 个端点。B站能力由宿主进程直接 import SDK</td></tr><tr><td>反馈与记忆分两条路</td><td>反馈进 <code>feedback/entries.jsonl</code>（给你看工具哪里不顺手），一轮最多 3 条；记忆进口味图</td></tr></tbody></table><h3 id="_5-3-宪章归使用者-系统只讲规则" tabindex="-1">5.3 宪章归使用者，系统只讲规则 <a class="header-anchor" href="#_5-3-宪章归使用者-系统只讲规则" aria-label="Permalink to &quot;5.3 宪章归使用者，系统只讲规则&quot;">​</a></h3><p>使用者原话：<em>「系统提示词少即是多，讲清楚规则；宪章等约束应该我在设置里写。」</em></p><ul><li>配置项 <code>rulesExtra</code>（设置 → 偏好 → <strong>额外约束</strong>）：使用者自己写的话<strong>原样</strong>注入三个轮次的开头， 优先级高于它自己的口味推断；留空 ⇒ 这一段根本不存在。</li><li>提示词只写<strong>操作规则</strong>（工具范围、边界、预算、红线的执行部分），不写价值判断。 曾把「不谈政治、不吵架」写进回私信章程，被使用者否掉：那等于替 Agent 做了本该由使用者决定的取舍， 结果正常聊天也会被「我们不谈政治」挡回来。<strong>这类内容归 <code>rulesExtra</code>，不归系统。</strong></li><li>瘦身结果：<code>charter.md</code> 10763 → 3256 字（-70%）、<code>consolidate.md</code> 2378 → 2016、<code>reply.md</code> 1641 → 1349； 全部 emoji 清零（含 ✓ / ✗ 这类符号），说明性文字砍掉，保留可执行的规则。</li><li>生成的 prompt 段同样只留<strong>这一轮的变量</strong>（额度 / 参考方向 / 待看队列 / 关注额度）， 规则交给章程，不重复。</li></ul><hr><h2 id="_6-设置页" tabindex="-1">6. 设置页 <a class="header-anchor" href="#_6-设置页" aria-label="Permalink to &quot;6. 设置页&quot;">​</a></h2><h3 id="_6-1-五个页签" tabindex="-1">6.1 五个页签 <a class="header-anchor" href="#_6-1-五个页签" aria-label="Permalink to &quot;6.1 五个页签&quot;">​</a></h3><table tabindex="0"><thead><tr><th>页签</th><th>管什么</th><th>典型控件</th></tr></thead><tbody><tr><td><strong>日常</strong></td><td>自动刷总开关、时段列表、每天最多挑几条、现在跑一轮、今日进度</td><td><code>Switch</code>、行内 <code>Input</code> + 删除、<code>Pill</code> 快捷值</td></tr><tr><td><strong>偏好</strong></td><td>人设、参考方向、排除词及其用法、搜索排序 / 翻页、日报形态、关注 UP、取帧方式与质量</td><td>Tag 编辑器、<code>SegmentedControl</code>、数字 <code>Input</code></td></tr><tr><td><strong>投递</strong></td><td>投递模式、白名单 UID、私信监听、AI 的收藏夹（选 / 新建）</td><td>Tag 编辑器（数字校验）、<code>Menu</code> + <code>MenuItemButton</code></td></tr><tr><td><strong>上下文</strong></td><td>三种轮次<strong>真正注入</strong>的 prompt，按段展示</td><td><code>SegmentedControl</code> + <code>DisclosureRow</code> + <code>CodeBlock</code></td></tr><tr><td><strong>高级</strong></td><td>模型、运行、记忆、用量、反馈、日志、危险区（7 个子页签）</td><td>子页签 + 卡片 + 预算条</td></tr></tbody></table><ul><li>控件全部走 DSH 共享原语（<code>@deepseek-ai/dsh-client-ui-primitives</code>），<strong>不手搓</strong>；<code>require</code> 不到就整套降级成朴素控件，绝不白屏。</li><li>判定原语是否可用必须用 <code>isComp()</code>：真宿主里 <code>Button</code> / <code>Input</code> 是 <code>forwardRef</code> 的产物，导出的是对象，只判 <code>typeof === &#39;function&#39;</code> 会把「组件全齐」误判成缺 3 个、整套降级。排查入口：页面根节点 <code>data-bh-ui=&quot;primitives|fallback&quot;</code> + <code>window.__BH_PRIM_ERR__</code>。</li><li>只用内联样式：<code>&lt;style&gt;</code> + 属性选择器在这个宿主里实测不生效。</li></ul><h3 id="_6-2-零保存按钮-即时保存" tabindex="-1">6.2 零保存按钮 + 即时保存 <a class="header-anchor" href="#_6-2-零保存按钮-即时保存" aria-label="Permalink to &quot;6.2 零保存按钮 + 即时保存&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>触发</th></tr></thead><tbody><tr><td><code>Switch</code> / <code>SegmentedControl</code> / Tag 增删 / 删时段</td><td>改动立即 <code>POST /config</code></td></tr><tr><td>数字 / 文本 / 时段编辑</td><td>600ms 防抖</td></tr></tbody></table><p>状态机固定宽度，<code>idle → dirty → saving → saved → idle</code>，<strong>永远不推动布局</strong>；失败时该控件标红 + <code>Toast</code>，本地草稿保留。除「清除」这种不可逆动作，界面上没有任何保存按钮。</p><h3 id="_6-3-上下文页" tabindex="-1">6.3 上下文页 <a class="header-anchor" href="#_6-3-上下文页" aria-label="Permalink to &quot;6.3 上下文页&quot;">​</a></h3><ul><li>三个 mode（值班 / 整理 / 回私信），每个都显示总字符数、估算 token、段数。</li><li>每段可折叠展开成可复制的 <code>CodeBlock</code>，并标出<strong>来源</strong>：<code>prompts/charter.md</code>、<code>设置 · 人设</code>、<code>设置 · 排除词（excludeMode=hard）</code>、<code>自动生成（额度 / 已挑数）</code>、<code>固定（素材不是指令）</code>……</li><li>改完设置立刻能看到它改了哪一段。数据源：<code>GET /prompt-preview?mode=duty|consolidate|reply</code>。</li></ul><h3 id="_6-4-高级-→-记忆" tabindex="-1">6.4 高级 → 记忆 <a class="header-anchor" href="#_6-4-高级-→-记忆" aria-label="Permalink to &quot;6.4 高级 → 记忆&quot;">​</a></h3><ul><li>六类节点的预算条 + 关系边预算条（超过 85% 变红），一行汇总：图体积 / 注入文本 <code>chars/budget</code> / 冷归档体积 / 旧 <code>MEMORY.md</code> 是否还没拆。</li><li>「立即整理」直接开一轮巩固；「看注入文本」展开 DIGEST 全文；「清空…」直接跳到清除对话框并预勾「记忆」。</li><li>「查它的记忆」：<code>/memory/graph?q=</code> 搜索 → 点开 <code>/memory/node?id=</code> 看一跳邻居（带方向、关系、权重、是否失效）。</li><li>「口味演化」：列出已失效的旧结论（<code>until</code> 有值的节点/边），按时间倒序。</li></ul><h3 id="_6-5-清除-agent-三步确认" tabindex="-1">6.5 清除 Agent：三步确认 <a class="header-anchor" href="#_6-5-清除-agent-三步确认" aria-label="Permalink to &quot;6.5 清除 Agent：三步确认&quot;">​</a></h3><ol><li><code>Modal</code> 列出<strong>将要删除的具体文件 + 字节数</strong>（<code>GET /reset/preview</code>）。</li><li>勾选「我知道这会…」+ <strong>手打</strong>「清除」两个字。</li><li>按钮解禁 → <code>POST /reset {items, phrase:&quot;清除&quot;}</code>。</li></ol><p>服务端二次校验：<code>phrase</code> 必须严格等于「清除」（多一个空格都 400）、<code>items</code> 必须全在白名单、非空。<strong>先备份后删</strong>：整包移到 <code>~/.dsh/bili-hello/.trash/&lt;ts&gt;/</code>，返回备份路径，可反悔。</p><p>可清除项：<code>memory</code> / <code>logs</code> / <code>prompts</code>（恢复出厂）/ <code>config</code> / <code>credential</code>（登出）。</p><hr><h2 id="_7-http-api" tabindex="-1">7. HTTP API <a class="header-anchor" href="#_7-http-api" aria-label="Permalink to &quot;7. HTTP API&quot;">​</a></h2><p>前缀 <code>/api/bili-hello</code>。全部响应是 <code>{ok:true,...}</code> 或 <code>{ok:false,reason}</code>。</p><table tabindex="0"><thead><tr><th>方法</th><th>路径</th><th>干什么</th></tr></thead><tbody><tr><td>GET</td><td><code>/status</code></td><td>插件总状态（登录 / 自动刷 / 时段 / 今日进度 / profile 是否就位）</td></tr><tr><td>GET · POST</td><td><code>/config</code></td><td>读 / 写配置（POST 做键白名单 + 类型校验）</td></tr><tr><td>POST</td><td><code>/run</code></td><td>立刻跑一轮值班</td></tr><tr><td>POST</td><td><code>/consolidate</code></td><td>立刻跑一轮巩固</td></tr><tr><td>GET</td><td><code>/models</code></td><td>值班 profile 真能用的 provider / 模型</td></tr><tr><td>GET</td><td><code>/me</code> · <code>/user?ids=</code></td><td>当前登录账号 / 指定 uid 的用户信息</td></tr><tr><td>GET</td><td><code>/metrics?days=14</code></td><td>token 用量（按轮型分开记）</td></tr><tr><td>GET</td><td><code>/report?day=</code></td><td>某天日报正文</td></tr><tr><td>GET · POST</td><td><code>/folders</code> · <code>/folder</code></td><td>收藏夹列表 / 新建</td></tr><tr><td>GET</td><td><code>/folder?id=</code></td><td>单个收藏夹内容</td></tr><tr><td>GET</td><td><code>/log?lines=200</code></td><td>日志尾部</td></tr><tr><td>GET</td><td><code>/feedback</code></td><td>Agent 自己提的反馈（按类型 / 日期聚合）</td></tr><tr><td>POST · GET · POST</td><td><code>/login/start</code> · <code>/login/poll</code> · <code>/logout</code></td><td>扫码登录三步 / 登出</td></tr><tr><td>GET</td><td><code>/prompt-preview?mode=</code></td><td>三种轮次真实注入的分段（含总字符、估算 token、每段来源）</td></tr><tr><td>GET</td><td><code>/reset/preview</code></td><td>清除预演：每项会删哪些文件、多少字节</td></tr><tr><td>POST</td><td><code>/reset</code></td><td>真删（<code>phrase</code> 必须是「清除」，先备份到 <code>.trash</code>）</td></tr><tr><td>GET</td><td><code>/memory</code></td><td>记忆总览（stats + digest + 旧版是否还在）</td></tr><tr><td>GET</td><td><code>/memory/stats</code></td><td>每类节点数 / 边数 / 预算占用 / 驱逐计数</td></tr><tr><td>GET</td><td><code>/memory/digest</code></td><td>DIGEST 全文 + 字符数 / 预算</td></tr><tr><td>GET</td><td><code>/memory/graph?type=&amp;q=</code></td><td>节点列表（可搜索、分页）</td></tr><tr><td>GET</td><td><code>/memory/node?id=</code></td><td>节点 + 一跳邻居</td></tr><tr><td>GET</td><td><code>/memory/history</code></td><td>已失效的节点 / 边，按时间倒序 = 口味演化</td></tr><tr><td>GET</td><td><code>/memory/search?q=</code></td><td>冷归档检索</td></tr><tr><td>POST</td><td><code>/memory/ops</code></td><td>手工提交一批 op（writer=<code>consolidator</code>）</td></tr></tbody></table><p>路由用 <strong>prefix</strong> 注册（<code>kind:&#39;prefix&#39;</code>）。坑：<code>exact</code> 只匹配 <code>/api/bili-hello</code> 字面路径，客户端请求的是子路径，会全部 404。</p><hr><h2 id="_8-文件地图" tabindex="-1">8. 文件地图 <a class="header-anchor" href="#_8-文件地图" aria-label="Permalink to &quot;8. 文件地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>一行说明</th></tr></thead><tbody><tr><td><code>index.js</code></td><td>宿主半端：配置 / 定时 / 子进程 / 私信白名单 / 收藏夹 / 记忆 API / HTTP 路由；<code>isRound()</code> 分支负责值班轮那一侧</td></tr><tr><td><code>client.js</code></td><td>浏览器半端：设置页五页签 + 高级页 7 个子页签，全部内联样式 + 共享原语</td></tr><tr><td><code>lib/memory.mjs</code></td><td>记忆引擎：图模型、硬预算、驱逐、DIGEST 渲染、journal 事件溯源</td></tr><tr><td><code>lib/memory-ops.mjs</code></td><td>模型原始输出 → 可执行 op（JSON 容错解析 + 行式 DSL 兜底）</td></tr><tr><td><code>lib/memwire.mjs</code></td><td>接线层：渲染注入文本、提交 op、跨会话共享状态（配额 / 队列 / 暂停 / 停跑请求 / 上一轮）</td></tr><tr><td><code>lib/tools.mjs</code></td><td>窄工具集（按 mode 注册）+ 七个协调者工具</td></tr><tr><td><code>lib/state.mjs</code></td><td>家目录契约、章程铺装（改过的保留）、清除 Agent 的白名单与备份</td></tr><tr><td><code>lib/schedule.mjs</code></td><td>时段判断（跨零点）、下一次窗口、跨零点的单测友好实现</td></tr><tr><td><code>lib/metrics.mjs</code></td><td>token 用量（从 llm/stream 的 usage chunk 里捞）</td></tr><tr><td><code>lib/dmwatch.mjs</code></td><td>私信监听一跳（先跑成再记账 + 陌生人抑制）</td></tr><tr><td><code>lib/vision.mjs</code></td><td>看画面：故事板裁帧 / 网格长图 / DASH Range + ffmpeg；图床请求不带 Cookie</td></tr><tr><td><code>lib/feedback.mjs</code></td><td>Agent 的用户反馈通道（与记忆分开）</td></tr><tr><td><code>lib/bili.mjs</code></td><td>凭证文件 → BiliContext</td></tr><tr><td><code>lib/hostdeps.mjs</code></td><td>从宿主那棵树里取 <code>@deepseek-ai/*</code>（optional peer，裸 import 会让插件不激活）</td></tr><tr><td><code>lib/loginweb.mjs</code></td><td>设置页扫码登录（QR + 轮询 + 落凭证）</td></tr><tr><td><code>lib/uinfo.mjs</code></td><td>uid → 昵称/头像 的三级缓存：内存 Map + 磁盘 JSON（<code>cache/users.json</code>）+ 负缓存；串行请求、260ms 间隔、单次 ≤20 个 —— B站 用户接口有频控（踩过 <code>-509</code>）</td></tr><tr><td><code>prompts/charter.md</code></td><td>值班章程：收藏家人设、工具即边界、防注入红线</td></tr><tr><td><code>prompts/consolidate.md</code></td><td>巩固章程：op 词表 + 什么值得变成操作</td></tr><tr><td><code>prompts/reply.md</code></td><td>回私信章程：怎么说人话 + 协调者职责 + 不能做什么</td></tr><tr><td><code>profile-template/bili-hello-duty/</code></td><td>值班轮专用最小权限 profile（安全边界本身）</td></tr><tr><td><code>bin/bh.mjs</code> · <code>bin/config.mjs</code> · <code>bin/login.mjs</code></td><td>命令行：状态 / 改配置 / 外接扫码登录</td></tr><tr><td><code>tools/shot.mjs</code> · <code>tools/testdsh.sh</code></td><td>CDP 截图 / 起一个隔离 DSH 实例</td></tr></tbody></table><p>家目录（<code>$DSH_HOME/bili-hello/</code>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>config.json          配置（设置页与 bin/config.mjs 写同一份）</span></span>
<span class="line"><span>credential.json      凭证（插件只读）</span></span>
<span class="line"><span>duty-overlay.yml     运行时 overlay：这一轮用哪个模型</span></span>
<span class="line"><span>prompts/             三份章程（你改过的保留，新版落 .new）</span></span>
<span class="line"><span>out/&lt;日期&gt;.md        日报</span></span>
<span class="line"><span>memory/              journal/ · graph.json · DIGEST-*.md · archive/ · scratch/</span></span>
<span class="line"><span>state/               quota.json · queue.json · pause.json · run-pending.json · last-round.json</span></span>
<span class="line"><span>metrics/&lt;日期&gt;.jsonl 一行一次模型调用</span></span>
<span class="line"><span>duty.log             日志</span></span>
<span class="line"><span>.trash/&lt;ts&gt;/         清除前的备份</span></span></code></pre></div><hr><h2 id="_9-怎么验证" tabindex="-1">9. 怎么验证 <a class="header-anchor" href="#_9-怎么验证" aria-label="Permalink to &quot;9. 怎么验证&quot;">​</a></h2><table tabindex="0"><thead><tr><th>手段</th><th>干什么</th></tr></thead><tbody><tr><td><code>npm test</code></td><td><code>node --test --test-concurrency=2 test/</code>，22 组 / <strong>343 例</strong>全绿（实测约 30 秒）</td></tr><tr><td><code>UPDATE_GOLDENS=1 node --test test/prompt-preview.test.mjs</code></td><td>提示词快照在 <code>test/fixtures/prompt-*.txt</code>，改措辞后一键重生成，不用手改测试数组</td></tr><tr><td><code>node bin/bh.mjs</code></td><td>命令行口子：<code>status</code> <code>cfg</code> <code>set k=v</code> <code>get &lt;path&gt;</code> <code>post &lt;path&gt;</code> <code>preview duty|consolidate|reply</code> <code>run</code> <code>consolidate</code> <code>memory</code> <code>reset</code></td></tr><tr><td><code>node tools/shot.mjs --port &lt;p&gt;</code></td><td>chrome-headless-shell + CDP 截图，三种视口，能抓控制台错误；改 UI 必须真看图</td></tr><tr><td><code>tools/testdsh.sh start|stop|restart</code></td><td>起第二个隔离实例（<code>BILI_HELLO_DIR</code> 隔离插件状态），不碰正在用的那个</td></tr><tr><td><code>dsh --profile bili-hello-duty --dump-config</code></td><td>只读验证 profile 组装：<code>tool-fs</code> / <code>tool-bash</code> / <code>tool-web</code> / <code>tool-subagent</code> / <code>skill</code> 应全是 <code>disabled: true</code></td></tr></tbody></table><p>真机跑通过的事实（隔离实例，<code>BILI_HELLO_DIR</code> 指向开发目录）：</p><ul><li><strong>值班轮</strong>：手动轮 <code>exit=0</code>，挑 3 条（1 条读完字幕定值得看、1 条人物片、1 条仅凭弹幕标签定可以看），跳过 6 条并写明原因（无字幕 / 字幕只有署名 / 取帧工具报错）。</li><li><strong>巩固轮</strong>：42 秒，提交 <strong>9 条 op 全部生效</strong>（<code>obs</code> 强化 UP→主题、<code>mk</code> 主题与悬念、<code>link</code> 子主题归入大类），当场返回的预算是 <code>up 2/80 · topic 3/60 · taste 2/24 · open 2/16 · 边 7/600 · 注入文本 194/4000</code>。</li><li>私信轮：非白名单 UID 提示「未读 3 条，按规矩不回」只记一次；<code>-509 请求过于频繁</code> 时只写日志，不抛。</li></ul><hr><h2 id="_10-实现与文档的出入" tabindex="-1">10. 实现与文档的出入 <a class="header-anchor" href="#_10-实现与文档的出入" aria-label="Permalink to &quot;10. 实现与文档的出入&quot;">​</a></h2><p>代码是准的，下面这些文档还欠更新：</p><table tabindex="0"><thead><tr><th>位置</th><th>文档说</th><th>代码实际</th></tr></thead><tbody><tr><td><code>README.md</code> 记忆章节</td><td>三层：<code>MEMORY.md</code> / <code>episodic/</code> / <code>archive/*.md</code></td><td>v2 已作废那一套：journal + graph.json + archive/*.jsonl + DIGEST</td></tr><tr><td><code>README.md</code> 设置章节</td><td>四个页签、24 个 B站工具</td><td>五页签；按模式 27 / 5 / 31</td></tr><tr><td><code>README.md</code> 测试章节</td><td>「30 个用例」</td><td>337 例</td></tr><tr><td><code>AGENTS.md</code> 第 6 条</td><td>343 个用例</td><td>343 例（已同步）</td></tr><tr><td><code>DESIGN.md</code> §2</td><td>「记忆三层」（v1 描述）</td><td>与 §9 / §10 自相矛盾，那份表已过时</td></tr><tr><td><code>DESIGN.md</code> §9.7</td><td>op 白名单 7 种</td><td>9 种（多 <code>unlink</code> / <code>unpin</code>，<code>prompts/consolidate.md</code> 也是 9 种）</td></tr><tr><td><code>DESIGN.md</code> §9.8</td><td><code>memory_node_get</code> ≤1200 字、<code>memory_recall</code> ≤20 条 ×200 字</td><td>分别截 1600 字符；recall 默认 10 条、上限 40 条、整段再截 4000 字符</td></tr><tr><td><code>DESIGN.md</code> §3.5</td><td>高级页一个「Metrics」折叠项</td><td>七个子页签（模型 / 运行 / 记忆 / 用量 / 反馈 / 日志 / 危险）</td></tr></tbody></table>`,41))])}const k=n(g,[["render",m]]);export{T as __pageData,k as default};
